() => {
  // Capture toast by observing DOM mutations for a few seconds
  return new Promise(resolve => {
    const seen = [];
    const obs = new MutationObserver(() => {
      document.querySelectorAll('div,span,p').forEach(el => {
        if (el.children.length === 0) {
          const t = el.textContent.trim();
          if (t && (t.includes('导出') || t.includes('水印') || t.includes('CSV')) && t.length < 120) {
            if (!seen.includes(t)) seen.push(t);
          }
        }
      });
    });
    obs.observe(document.body, { childList: true, subtree: true });
    const btn = Array.from(document.querySelectorAll('button')).find(b => b.innerText.trim() === '导出 CSV');
    if (btn) btn.click();
    setTimeout(() => { obs.disconnect(); resolve({ clicked: !!btn, seen }); }, 4000);
  });
}

