      resolve({ clicked: !!btn, downloads, toast: seen });
    }, 4000);
  });
}

() => {
  return new Promise(resolve => {
    let capturedBlob = null;
    const origCreate = URL.createObjectURL.bind(URL);
    URL.createObjectURL = function(blob) {
      capturedBlob = blob;
      return origCreate(blob);
    };
    const btn = Array.from(document.querySelectorAll('button')).find(b => b.innerText.trim() === '导出 CSV');
    if (btn) btn.click();
    setTimeout(async () => {
      URL.createObjectURL = origCreate;
      if (!capturedBlob) return resolve({ clicked: !!btn, captured: false });
      const text = await capturedBlob.text();
      const lines = text.split('\n');
      resolve({
        clicked: true,
        captured: true,
        blobType: capturedBlob.type,
        blobSize: capturedBlob.size,
        totalLines: text.trim().split('\n').length,
        firstLine: lines[0],
        headerLine: lines[1],
        firstDataLine: lines[2]
      });
    }, 4000);
  });
}
